const int NUM_TEMAS = (int)(sizeof TEMAS / sizeof TEMAS[0]);
const Tema* temaActual = &TEMAS[0];
static int elegido;

const Tema& TemaDe(int i) { return TEMAS[i >= 0 && i < NUM_TEMAS ? i : 0]; }
void TemaElegir(int i)
{
    elegido = i >= 0 && i < NUM_TEMAS ? i : 0;
    temaActual = &TEMAS[elegido];
}
int TemaElegido() { return elegido; }
